mutants = [m for m in mutants if m is not None]

def run_one(entry):
    name, rel, old, new = entry[:4]
    want_fail = entry[4] if len(entry) > 4 else name != 'unchanged'
    tmp = tempfile.mkdtemp(prefix='azl_pol_')
    base = os.path.join(tmp, 'AzaharLink')
    try:
        for d in dirs:
            shutil.copytree(os.path.join(root, d), os.path.join(base, d))
        for f in files:
            dst = os.path.join(base, f)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy(os.path.join(root, f), dst)
        if os.path.isdir(dlp_root):
            for d in dlp_dirs:
                shutil.copytree(os.path.join(dlp_root, d), os.path.join(tmp, 'DlpLink', d), ignore=shutil.ignore_patterns('research', '__pycache__'))
            for f in dlp_files:
                dst = os.path.join(tmp, 'DlpLink', f)
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy(os.path.join(dlp_root, f), dst)
        if rel:
            p = os.path.normpath(os.path.join(base, rel))
            if not os.path.exists(p):  # a file that must not exist (dist/default.3gx): the mutant makes it
                os.makedirs(os.path.dirname(p), exist_ok=True)
                open(p, 'wb').write(b'')
            if old is BYTE:
                data = bytearray(open(p, 'rb').read())
                data[new[0]] = new[1]
                open(p, 'wb').write(bytes(data))
            elif old is FUNC:
                changed = new(open(p, 'rb').read())   # (read first: opening for writing empties the file)
                open(p, 'wb').write(changed)
            elif old is GONE:
                os.remove(p)
            else:
                raw = open(p, 'rb').read().decode('utf-8')
                crlf = '\r\n' in raw
                s = raw.replace('\r\n', '\n')
                if old is APPEND:
                    s = s + new
                else:
                    n = s.count(old)
                    if n != 1:  # (a pattern not found once: the mutant is not applied, counted as not caught, and the others still run)
                        return False, 'BAD  ' + name + ' -> pattern found %d times, not once' % n
                    s = s.replace(old, new)
                open(p, 'wb').write((s.replace('\n', '\r\n') if crlf else s).encode('utf-8'))
        r = subprocess.run(['bash', 'Tests/policy_check.sh'], cwd=base, capture_output=True, text=True)
        ok = (r.returncode != 0) == want_fail
        first = (r.stdout.strip().splitlines() or [''])[0][:150]
        return ok, ('OK   ' if ok else 'BAD  ') + name + ' -> exit ' + str(r.returncode) + ' | ' + first
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# Each mutant is a private copy in its own temporary folder, so they run side by side (the checks are bash processes: the time is theirs).
failed = 0
if os.environ.get('MUTANT_FILTER'):
    import re
    wanted = re.compile(os.environ['MUTANT_FILTER'])
    mutants = [m for m in mutants if m[0] == 'unchanged' or wanted.search(m[0])]
if os.environ.get('MUTANT_FROM'):
    first = int(os.environ['MUTANT_FROM'])
    mutants = [m for i, m in enumerate(mutants) if i == 0 or i >= first]
with concurrent.futures.ThreadPoolExecutor(max_workers=int(os.environ.get('MUTANT_JOBS', '8'))) as pool:
    for ok, line in pool.map(run_one, mutants):
        print(line, flush=True)
        failed += 0 if ok else 1
print('%d mutants not caught (of %d, the unchanged copy included)' % (failed, len(mutants)))
sys.exit(1 if failed else 0)
